export const FLIGHT_GOAL=15, FLIGHT_DURATION=40;
export function createFlight(width=900,height=480){return {width,height,x:width*.22,y:height*.55,score:0,health:3,time:0,spawn:0,count:0,invincible:0,objects:[],status:'playing'}}
export function stepFlight(state,seconds,input={},random=Math.random){if(state.status!=='playing')return state;const dt=Math.max(0,Math.min(seconds,.05));state.time+=dt;state.invincible=Math.max(0,state.invincible-dt);if(input.target){state.x+=(input.target.x-state.x)*Math.min(1,dt*9);state.y+=(input.target.y-state.y)*Math.min(1,dt*9)}else{state.x+=(input.x||0)*360*dt;state.y+=(input.y||0)*360*dt}state.x=Math.max(46,Math.min(state.width*.78,state.x));state.y=Math.max(50,Math.min(state.height-50,state.y));state.spawn-=dt;
if(state.spawn<=0){state.count++;state.objects.push({x:state.width+30,y:65+random()*(state.height-130),type:state.count%3===0?'ink':'spark',phase:random()*Math.PI*2});state.spawn=.72}
for(const object of state.objects){object.x-=(220+state.score*3)*dt;const distance=Math.hypot(object.x-state.x,object.y-state.y);if(distance<(object.type==='spark'?36:37)){if(object.type==='spark'){state.score++;object.remove=true}else if(state.invincible===0){state.health--;state.invincible=1.4;object.remove=true}}}
state.objects=state.objects.filter(o=>!o.remove&&o.x>-50);if(state.score>=FLIGHT_GOAL)state.status='won';else if(state.health<=0)state.status='crashed';else if(state.time>=FLIGHT_DURATION)state.status='timeout';return state}
export function checkSignal(sequence,entered){if(entered.some((v,i)=>v!==sequence[i]))return 'wrong';return entered.length===sequence.length?'complete':'continue'}
